import{z as B,x as i,o as t,c as p,q as r,j as n,D as A,d as e,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"T+1 与回转交易约束","description":"","frontmatter":{"title":"T+1 与回转交易约束","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-tplus1.md","filePath":"quant/cn-tplus1.md","lastUpdated":1791413859000}'),d={name:"quant/cn-tplus1.md"};function m(h,a,D,T,u,c){const l=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="t-1-与回转交易约束" tabindex="-1">T+1 与回转交易约束 <a class="header-anchor" href="#t-1-与回转交易约束" aria-label="Permalink to &quot;T+1 与回转交易约束&quot;">​</a></h1><div class="epigraph"><p>投资者买入的证券，在交收前不得卖出，但实行回转交易的除外。证券的回转交易是指投资者买入的证券，经确认成交后，在交收前全部或部分卖出。</p><footer>—— 《上海证券交易所交易规则（2026 年修订）》第 3.1.4 条；深交所交易规则有对应表述</footer></div><p><a href="/quant/calendar-overnight">上一课</a>把日历收成隔夜与日内两段：开收盘字段、拍卖与 T+1 决定「隔夜」的含义。本课打开中国市场微观结构。美股常说的 T+1 多指清算交收周期缩短；交易层面仍允许当日买卖同一股票。A 股的约束更硬：股票竞价交易默认<strong>交收前回转受限</strong>，当日买入的股票不能当日卖出。上交所《交易规则》第 3.1.4–3.1.5 条把原则与例外写死：债券 ETF、货币 ETF、黄金 ETF、商品期货 ETF、跨境 ETF 与跨境 LOF（跟踪标的本身当日回转）、权证等实行当日回转；B 股为次一交易日起回转；普通 A 股股票不在当日回转名单里。中国结算对 A 股证券交收为 T+1，与交易侧的不可回转叠加。本篇只解释公开规则如何改写库存、奖励与对冲，不讨论任何绕过交收前不得卖出的做法。它直接改写<a href="/quant/calendar-overnight">日历与隔夜</a>和<a href="/quant/trading-mdp-pitfalls">交易 MDP</a>里的状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略语言里的「仓位」常是一个标量 \\(q_t\\)。T+1 下至少要拆成：昨日及更早持仓形成的<strong>可卖量</strong> \\(q^{\\mathrm{sell}}_t\\)，以及今日买入形成的<strong>锁定量</strong> \\(q^{\\mathrm{lock}}_t\\)。卖出只能动 \\(q^{\\mathrm{sell}}\\)；买入增加 \\(q^{\\mathrm{lock}}\\)，到次一交易日才并入可卖。资金侧不对称：卖出所得通常可用于当日再买入（具体可用时点以会员结算与中国结算备付为准），因此「先卖后买」与「先买后卖」不是同一操作。日频反转、做市式日内回转、以及「买错了立刻平掉」在股票上不可用。问题是把这条硬约束写进回测与风控，而不是在收盘价上来回画箭头。<span class="marginnote">数字实例：周一早盘买入 10 万股甲，这 10 万股全部进 \\(q^{\\mathrm{lock}}\\)，当天一股不能卖；周二开盘起才并入 \\(q^{\\mathrm{sell}}\\)。若周二想卖 15 万股而可卖只有 10 万，超出的 5 万股是整笔废单，不是「部分成交」。库存状态机必须按这笔账逐日滚动，废单日志就是它的对账单。</span></p><p>交收与交易要分开读。交易规则限制的是交收前卖出；结算规则决定法定所有权与资金何时完成交收。即使结算周期未来调整，只要第 3.1.4 条的交易限制仍在，日内卖出当日所买股票仍然不被主机接受。把 DTC 的 T+1 交收改革与 A 股回转限制当成同一制度，会在模拟器里放出非法动作。<span class="marginnote">常见误区：初学者容易把美股「结算周期缩短到 T+1」与 A 股「交易 T+1」当成一回事。美股缩短的只是钱券交收时间，当日买卖同一只股票始终合法；A 股卡的是交易环节本身——就算哪天结算改成 T+0，第 3.1.4 条不改，当日买入的股票仍然当日卖不掉。</span></p><h3 id="可卖量是状态-不是收盘持仓" tabindex="-1">可卖量是状态，不是收盘持仓 <a class="header-anchor" href="#可卖量是状态-不是收盘持仓" aria-label="Permalink to &quot;可卖量是状态，不是收盘持仓&quot;">​</a></h3><p>收盘持仓 \\(q^{\\mathrm{sell}}+q^{\\mathrm{lock}}\\) 看起来已经买到，却不能用于下午的对冲或止损。早盘买入、午后信号反号，股票策略只能持有到次日，隔夜风险强制暴露。这把「日频」策略的真正风险窗口拉长到开盘到次日可卖，而不是开盘到当日收盘。涨跌停再叠加：次日若一字板，可卖权存在但没有对手盘。回测若用当日收盘平仓价计算收益，是在虚构一个规则禁止的成交。正确的第一笔可平仓价格是次一交易日的可成交价，通常从开盘集合竞价算起。</p><p><span class="marginnote">融券卖出再买回、当日回转品种、以及债券逆回购，适用各自的规则，不能从股票 T+1 类推。本篇对象是竞价交易下未列入当日回转名单的 A 股股票。例外名单以交易所现行第 3.1.5 条及后续公告为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>回测引擎在每笔买入成交后，把量记入 \\(q^{\\mathrm{lock}}\\)，卖出订单的数量不得超过当时 \\(q^{\\mathrm{sell}}\\)，超出部分废单而不是部分虚构成交。日终，\\(q^{\\mathrm{lock}}\\) 转入下一日 \\(q^{\\mathrm{sell}}\\)（停牌、冻结、司法扣划等另按结算与会员规则）。信号若在 \\(t\\) 日收盘产生，股票买入在 \\(t\\) 日能执行，\\(t\\) 日不能反向卖出同一笔；卖出信号只能针对已有可卖库存。执行层应把「目标仓位」翻译成「对可卖库的减仓」与「对新买额度的加仓」两条指令，避免一个目标仓位数字直接生成一买一卖。</p><p>评价收益用可执行路径：买入以可获得信号之后的集合竞价或连续竞价成交，卖出不得早于该券可卖日。隔夜收益不再是可选择的因子，而是制度强制的持有。与美股日内策略对比时，必须声明 A 股版本是「隔夜强制版」，夏普不可横比。ETF 中在第 3.1.5 条名单内的品种，可单独标记为当日回转，用于对冲工具，而不是把股票也当成可回转。</p><h3 id="对冲与多腿" tabindex="-1">对冲与多腿 <a class="header-anchor" href="#对冲与多腿" aria-label="Permalink to &quot;对冲与多腿&quot;">​</a></h3><p>指数期货、期权与部分 ETF 的会话与交收与股票不同。用股指期货对冲当日买入的股票，可以减少隔夜 beta，但不能消除个股特异风险，也不是股票的回转。配对交易若两腿都是股票，开仓后当日不能同时反向平掉两腿；一腿若用期货替代，基差与涨跌停缺腿仍在，见<a href="/quant/index-arb">指数套利</a>。方法是在组合层记录每条腿的可卖日历，禁止生成「当日开当日平」的股票多空来回。风控的止损价在当日对新买腿不可执行，只能降为「次日开盘可成交则减仓」，并接受缺口。<span class="marginnote">直觉上，T+1 把每笔股票买入变成「今日寄出、明日签收」的快递——签收之前不能转手。所以止损价对当日新买的腿只是纸面数字：触发时你没有任何可卖量。风控应输出「次日开盘减仓」的预计缺口，而不是假设止损必然成交。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>T+1 把日内均值回复的可交易性切断。短周期反向若依赖当日平仓，纸面 IC 来自不可执行的路径。能留下的是隔夜到次日开盘的那一段，而这正是集合竞价与隔夜信息释放最剧烈的一段，见<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>。于是「日频反转」在 A 股往往退化成隔夜因子或次日开盘执行的隔夜动量，名称还叫反转，机制已经变了。</p><p>资金先卖后买，使调仓在减持旧仓、买入新名单时仍可在同一日完成，只要旧仓可卖。换仓能力来自可卖库存的周转，不是来自新买股票的回转。这解释了为何高换手策略在 A 股仍能换名单，却不能对同一只股票做日内来回。容量与冲击要从「跨股票换仓」去估，不要从「同股票日内双向」去估。</p>',17)),(t(),n(o,null,{default:A(()=>[s(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E4%BB%93%20q_sell%20%E4%BB%8A%E6%97%A5%E5%8F%AF%E5%8D%96%22%5D%20--%3E%20S%5B%22%E4%BB%8A%E6%97%A5%E5%8D%96%E5%87%BA%E6%97%A7%E4%BB%93%22%5D%0A%20%20S%20--%3E%20CASH%5B%22%E5%8D%96%E5%87%BA%E8%B5%84%E9%87%91%E5%BD%93%E6%97%A5%E5%8F%AF%E7%94%A8%22%5D%0A%20%20CASH%20--%3E%20B%5B%22%E4%B9%B0%E5%85%A5%E6%96%B0%E5%90%8D%E5%8D%95%E8%82%A1%E7%A5%A8%22%5D%0A%20%20B%20--%3E%20LOCK%5B%22%E6%96%B0%E4%B9%B0%E8%82%A1%E7%A5%A8%E9%94%81%E5%AE%9A%20%E6%AC%A1%E6%97%A5%E6%89%8D%E5%8F%AF%E5%8D%96%22%5D%0A%20%20OLD%20--%3E%20OK%5B%22%E8%B7%A8%E8%82%A1%E7%A5%A8%E6%8D%A2%E4%BB%93%20%E5%BD%93%E6%97%A5%E5%AE%8C%E6%88%90%20%E5%90%88%E6%B3%95%22%5D%0A%20%20SAMESAME%5B%22%E5%90%8C%E4%B8%80%E5%8F%AA%E8%82%A1%E7%A5%A8%20%E5%BD%93%E6%97%A5%E4%B9%B0%E5%8F%88%E5%BD%93%E6%97%A5%E5%8D%96%22%5D%20--%3E%20NO%5B%22%E5%89%8D%E7%AB%AF%E6%A3%80%E6%9F%A5%E6%8B%92%E7%BB%9D%20%E5%BA%9F%E5%8D%95%22%5D%0A%20%20SAMESAME%20-.-%3E%7C%22%E5%8F%AA%E8%83%BD%E6%AC%A1%E6%97%A5%E5%8D%96%22%7C%20NEXT%5B%22%E9%9A%94%E5%A4%9C%E9%A3%8E%E9%99%A9%E5%BC%BA%E5%88%B6%E6%89%BF%E6%8B%85%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">北向沪深港通投资者同样不可对通股票做即日买卖，前端检查要求卖出前账户内已有证券。境外 T+0 习惯不能经港股通通道进口到 A 股股票上。</span></p><h3 id="与交收周期、融资融券的交界" tabindex="-1">与交收周期、融资融券的交界 <a class="header-anchor" href="#与交收周期、融资融券的交界" aria-label="Permalink to &quot;与交收周期、融资融券的交界&quot;">​</a></h3><p>融资买入的证券作为担保物，其处置与平仓遵循《证券公司融资融券业务管理办法》及交易所实施细则，不等于恢复股票当日回转。融券卖出后买券还券的时点，也受合约与细则约束，不能写成无限制的日内空头回转。把融资融券当成 T+0 通道，既不符合管理办法对交易与担保的规定，也不属于本篇允许讨论的范围。公开规则下，股票竞价的回转名单以交易所公告为准，策略只能订阅名单，不能创造名单之外的回转。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>规则会修订。上交所 2026 年修订仍保留第 3.1.4 条的原则，并列举当日回转品种；回测历史必须用当时有效的名单与交收制度，而不是用今日名单回填 2010 年。ETF 纳入或移出当日回转，会突然改变对冲工具集合。B 股、存托凭证、北交所另有条文，不要与沪深 A 股股票混用一个库存状态机。</p><p>不要在研究里用收盘价减开盘价当股票的「日内可实现收益」并据此调仓。不要为了拟合美股论文而关闭 T+1。不要把结算 T+1 改革的新闻理解成交易 T+0。模拟器应在废单日志里统计「超过可卖量」的次数；若次数为零却声称有大量日内来回，引擎没有实现规则。</p><p><span class="marginnote">可卖量还受冻结、质押、司法扣划、未交收认购影响。交易规则给出的是一般原则；账户层以前端检查为准。回测至少实现交易规则这一层，实盘必须与会员柜台的持仓性质字段对齐。</span></p>',7)),(t(),n(o,null,{default:A(()=>[s(l,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUY%5B%22%E5%BD%93%E6%97%A5%E4%B9%B0%E5%85%A5%E6%88%90%E4%BA%A4%22%5D%20--%3E%20LOCK%5B%22%E9%94%81%E5%AE%9A%E9%87%8F%20q_lock%22%5D%0A%20%20LOCK%20--%3E%20NEXT%5B%22%E6%AC%A1%E4%B8%80%E4%BA%A4%E6%98%93%E6%97%A5%E8%BD%AC%E5%85%A5%E5%8F%AF%E5%8D%96%22%5D%0A%20%20OLD%5B%22%E6%98%A8%E6%97%A5%E5%8F%8A%E6%9B%B4%E6%97%A9%E6%8C%81%E4%BB%93%22%5D%20--%3E%20SELL%5B%22%E5%8F%AF%E5%8D%96%E9%87%8F%20q_sell%22%5D%0A%20%20SELL%20--%3E%20SORD%5B%22%E5%8D%96%E5%87%BA%E7%94%B3%E6%8A%A5%22%5D%0A%20%20SORD%20--%3E%20CASH%5B%22%E8%B5%84%E9%87%91%E5%8F%AF%E7%94%A8%E4%BA%8E%E5%BD%93%E6%97%A5%E5%86%8D%E4%B9%B0%22%5D%0A%20%20CASH%20--%3E%20BUY2%5B%22%E4%B9%B0%E5%85%A5%E5%85%B6%E4%BB%96%E6%88%96%E5%90%8C%E4%B8%80%E5%90%8D%E5%8D%95%E5%A4%96%E8%82%A1%E7%A5%A8%22%5D%0A%20%20LOCK%20-.-%3E%7C%22%E8%A7%84%E5%88%99%E7%A6%81%E6%AD%A2%22%7C%20NO%5B%22%E5%BD%93%E6%97%A5%E5%8D%96%E5%87%BA%E8%AF%A5%E7%AC%94%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"小结",tabindex:"-1"},[e("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=E("ul",null,[E("li",null,"A 股股票竞价交易默认交收前不得卖出；当日回转只适用于交易所列举的品种。"),E("li",null,"库存必须拆成可卖量与当日锁定量；先卖后买与先买后卖不对称。"),E("li",null,"日频回测用当日收盘平当日开仓，与《交易规则》第 3.1.4 条冲突。"),E("li",null,"强制隔夜改变短周期反转与止损的可执行路径，收益应从次日可成交价起算。"),E("li",null,"对冲可用其他品种的公开机制，但不能把股票写成 T+0。"),E("li",null,"出处：《上海证券交易所交易规则（2026 年修订）》第 3.1.4、3.1.5、2.4.2 条；深交所交易规则对应条款；中国结算 A 股交收安排。")],-1))])}const _=B(d,[["render",m]]);export{F as __pageData,_ as default};
